def countPalindromicSubsequences(s):
    MOD = 10**9 + 7
    n = len(s)
    # dp[i][j][k]: number of palindromic subsequences in s[i:j+1]
    # that start and end with chr(ord('a') + k)
    dp = [[[0] * 4 for _ in range(n)] for _ in range(n)]

    for i in range(n):
        for k in range(4):
            if ord(s[i]) - ord('a') == k:
                dp[i][i][k] = 1

    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            for k in range(4):
                ch = chr(ord('a') + k)
                if s[i] == s[j] == ch:
                    # 2: 'ch' and 'chch' (if i != j) + all palindromic subsequences inside
                    dp[i][j][k] = 2
                    if j > i + 1:
                        for m in range(4):
                            dp[i][j][k] += dp[i + 1][j - 1][m]
                    dp[i][j][k] %= MOD
                else:
                    val = 0
                    if s[i] != ch:
                        val += dp[i + 1][j][k]
                    if s[j] != ch:
                        val += dp[i][j - 1][k]
                    if s[i] != ch and s[j] != ch:
                        val -= dp[i + 1][j - 1][k]
                    dp[i][j][k] = val % MOD

    return sum(dp[0][n - 1][k] for k in range(4)) % MOD
